(6180793, 912807, 96751, '<td valign="top">Too funny!  Love the simplicity of this image, and the lovely tones.</td>', 'Too funny!  Love the simplicity of this image, and the lovely tones.', '2010-10-04 14:53:19.000000', NULL, 1),
(6180795, 912245, 96751, '<td valign="top">Lovely.  I''m a great fan of negative space, but even so, there is a bit too much of it here.</td>', 'Lovely.  I''m a great fan of negative space, but even so, there is a bit too much of it here.', '2010-10-04 14:56:09.000000', NULL, 1),
